package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Scanner struct {
	lines  []string
	index  int
	max    int
}

func NewScanner(lines []string) *Scanner {
	return &Scanner{lines: lines, index: 0, max: len(lines)}
}

func (s *Scanner) HasNext() bool {
	return s.index < s.max
}

func (s *Scanner) Next() string {
	if !s.HasNext() {
		panic("ArrayIndexOutOfBoundsException: There is no more input")
	}
	line := s.lines[s.index]
	s.index++
	return line
}

func NextInt(s *Scanner) int {
	line := s.Next()
	n, _ := strconv.Atoi(line)
	return n
}

func NextIntArray(s *Scanner) []int {
	line := s.Next()
	parts := strings.Fields(line)
	result := make([]int, len(parts))
	for i, p := range parts {
		result[i], _ = strconv.Atoi(p)
	}
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var lines []string
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}
		lines = append(lines, strings.TrimRight(line, "\n"))
	}

	s := NewScanner(lines)
	fmt.Fprintln(os.Stderr, "\n↑入力 ↓出力")

	N := NextInt(s)
	alist := NextIntArray(s)
	blist := NextIntArray(s)

	asum := 0
	bsum := 0
	for i := 0; i < N; i++ {
		asum += alist[i]
		bsum += blist[i]
	}

	if asum >= bsum {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
